#!/usr/bin/env bash
# Publish cvmfs/log.txt and cvmfs/applist.json for the apps.json revision whose
# images the upload job has just made available in object storage.
#
# main requires the "quality required" check, so the metadata reaches main
# through a pull request that is merged once branch protection accepts it.
set -euo pipefail

SOURCE_SHA="${1:?usage: publish_cvmfs_metadata.sh <uploaded-commit-sha>}"
BRANCH="${CVMFS_METADATA_BRANCH:-bot/cvmfs-metadata}"
BASE="${CVMFS_METADATA_BASE:-main}"
MERGE_ATTEMPTS="${CVMFS_METADATA_MERGE_ATTEMPTS:-80}"
MERGE_RETRY_DELAY="${CVMFS_METADATA_MERGE_RETRY_DELAY:-30}"
METADATA_FILES=(cvmfs/log.txt cvmfs/applist.json)

apps_json="$(mktemp)"
trap 'rm -f "$apps_json"' EXIT

git fetch --no-tags origin "$BASE"
git show "${SOURCE_SHA}:neurodesk/apps.json" > "$apps_json"
git checkout -B "$BRANCH" "origin/$BASE"
python3 cvmfs/generate_metadata.py \
    --apps-json "$apps_json" \
    --log cvmfs/log.txt \
    --applist cvmfs/applist.json

open_pr="$(gh pr list --base "$BASE" --head "$BRANCH" --state open --json number --jq '.[0].number // empty')"

if git diff --quiet -- "${METADATA_FILES[@]}"; then
    echo "[INFO] Published CVMFS metadata already matches ${SOURCE_SHA}."
    if [[ -n "$open_pr" ]]; then
        gh pr close "$open_pr" --comment "Superseded: $BASE already publishes the metadata for ${SOURCE_SHA}."
    fi
    exit 0
fi

git -c user.name="github-actions[bot]" \
    -c user.email="41898282+github-actions[bot]@users.noreply.github.com" \
    commit --quiet -m "Publish CVMFS metadata for uploaded containers" \
    -m "Generated from neurodesk/apps.json at ${SOURCE_SHA} after its images were uploaded." \
    -- "${METADATA_FILES[@]}"
git push --force origin "HEAD:refs/heads/$BRANCH"
head_sha="$(git rev-parse HEAD)"

if [[ -z "$open_pr" ]]; then
    gh pr create --base "$BASE" --head "$BRANCH" \
        --title "Publish CVMFS metadata for uploaded containers" \
        --body "Generated by the Update neurocontainers workflow from \`neurodesk/apps.json\` at ${SOURCE_SHA}, after every listed image was confirmed in Nectar and AWS object storage."
    open_pr="$(gh pr list --base "$BASE" --head "$BRANCH" --state open --json number --jq '.[0].number')"
fi

# Branch protection decides when the PR is mergeable; retry until its required
# checks pass on this exact head, or fail the job so the lag stays visible.
for ((attempt = 1; attempt <= MERGE_ATTEMPTS; attempt++)); do
    if gh pr merge "$open_pr" --squash --match-head-commit "$head_sha"; then
        echo "[INFO] Merged CVMFS metadata PR #${open_pr} for ${SOURCE_SHA}."
        exit 0
    fi
    if [[ $attempt -lt $MERGE_ATTEMPTS ]]; then
        echo "[INFO] PR #${open_pr} is not mergeable yet (attempt ${attempt}/${MERGE_ATTEMPTS}); retrying in ${MERGE_RETRY_DELAY}s."
        sleep "$MERGE_RETRY_DELAY"
    fi
done

echo "[ERROR] CVMFS metadata PR #${open_pr} was not merged; published metadata still lags ${SOURCE_SHA}."
exit 1
